from docx import Document
from docx.shared import Pt,Cm,RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
items=[]
def add(q,p,page): items.append((q,p,page))
add('在供应能力、运输费率和仓储容量等关键参数相对确定的情境下，有必要进一步探究如何统筹供应点配置、海外仓启用、货物流向与多环节成本控制','研究定位与后续模型不完全一致。第五章仅优化海外仓启用、需求分配和货物流量，未设置供应点启用的固定成本及相应选址约束。某供应点运输量为零只能表明本期未使用，不能直接解释为供应点选址或关闭。应统一问题定义、决策范围及后文“供应点选址结果”的表述。','69、76、81—84')
add('在空间层面，假设将供应点、仓库与需求点抽象为质点，运输路径采用欧几里得直线距离，并假设运输成本与距离线性相关','直线距离与本算例的跨海运输条件不匹配。东北内陆城市至日本、韩国通常涉及陆路集货、港口作业及海运，日韩间配送也涉及跨海运输。应采用可行的分段运输距离及费用，或验证直线距离近似对选址结果的影响。','69')
add('本章通过构建以“总成本最小化”为目标的跨境物流网络优化模型','“总成本”的核算边界需明确。目标只包含头程、配送及建仓成本，未单列仓储运营、装卸、通关等费用；若这些费用已包含在单位运价中，应明确说明。否则不能将计算结果泛称为物流全流程总费用。','70—71、77')
add('以便于构建单周期静态全局优化模型','单周期运输费用与一次性建仓投资的时间口径未统一。需求采用周需求量，建仓成本却直接全额计入同一目标，可能改变最优仓数。应明确规划期，对建设投资进行年金化或按使用寿命分摊，并将各项费用换算至同一期间。','70、73、75')
add('旨在为企业提供可操作的海外仓选址与网络布局方案','适用性表述过强。模型假设所有运输连接可行且不受物理或政策约束，未检验港口、通关、时效和进口准入条件。应补充实际可行性检验，或将结论限定为所设假设下的理论布局参考。','70')
add('按单位重量体积换算后的总体积之和，不能超过该海外仓库的最大容积','将一期累计出库体积直接等同于仓储占用量，混淆库存容量与期间吞吐量。仓库可在周期内周转，同期最大在库量未必等于累计出库量。应明确一次到货、一次出货等时序假设，或建立库存平衡与周转关系，再解释容量敏感性结果。','72、81—82')
add('本文选取选取哈尔滨、佳木斯、大连、营口、丹东五个东北地区核心粮食出口城市作为供应点','“选取选取”重复。另“五个核心粮食出口城市”的筛选依据未交代，应给出出口规模、粮源或物流节点地位等数据，以及候选供应点筛选标准。','72')
add('运输成本基于Freightos网站的40英尺集装箱费率结合节点间距离计算','数据处理过程不足以复现。应注明报价获取日期、航线、币种及汇率、报价是否包含附加费，并说明整箱报价如何转换为表中的单位商品运价，以及为何可再按距离计算。','73')
add('通过城市人口规模估算各城市（区域）三类农产品的周消费需求量','人口到需求的换算依据缺失。应提供人口统计年份、空间范围、人均消费或饲用需求系数及计算公式；同时区分城市总消费需求与由中国粮食进口承担的需求份额。三种粮食用途不同，仅按人口估计需作适用性说明。','73')
add('在仓储参数方面，设定供应点和海外仓统一规格为2万平方米（高度10米），海外仓最大容积利用率控制在80%','参数依据及有效容量核算不清。应说明统一仓库面积和高度的现实依据，是否扣除通道、消防及作业区，以及粮食堆存高度限制。第五章还未给出三类粮食的质量—体积换算数据，难以复核容量约束及可行性。','73')
add('建设成本则根据各城市GDP水平推算的单位面积工业土地价格计算','GDP不能直接替代工业用地价格，且土地取得费用不等于完整建仓费用。应提供估算关系、样本来源和校准依据，并说明建筑、设备及配套设施是否计入；否则表5.4的建设成本缺乏可核验依据。','73、75')
add('表5.1 头程运输成本：单位商品运输价格（元）','表中未说明“单位商品”对应一吨、一件还是一箱，而表5.3及运输量均以吨计。应补充运价的计费基准及换算方法；三种商品共用同一运价表的依据也需说明。此问题影响成本计算口径。','73—75')
add('表5.2 配送运输成本：单位商品运输价格（元）','表中不同城市间部分运价明显不对称，例如东京至大阪为55.67，大阪至东京为47.71。若采用第69页所述对称的直线距离及统一线性费率，应解释方向差异的来源；若使用方向性报价，应给出相应规则和数据来源。','69、74')
add('表5.2 配送运输成本：单位商品运输价格（元）','同城配送费用全部设为零，等于忽略仓库至实际客户的市内运输、装卸等成本，可能人为增加在需求城市建仓的吸引力。应给出零费用假设依据，或用合理市内配送成本做对照检验。','74')
add('利用GUROBI软件进行求解','求解报告不充分。应补充求解时间、停止条件、实际最优性间隙、最优界及模型规模；否则仅凭结果表不足以确认所称“最优解”。后文相对容量基准的成本差异不能替代求解器的最优性证明。','75—77、81')
add('表5.5 物流规划网络','表5.5与后续运输量表不一致。表5.5将川崎、神户、札幌列在川崎仓服务范围内，但表5.8将这三地分配给清州仓；同时表5.7显示大连、营口、丹东均向水原供货，表5.5的供应点—仓库对应关系未完整呈现。应按同一次求解结果重新核对整张表。','76—79')
add('表5.7 各商品由供应点至海外仓的货物运输量','水原仓水稻流量不守恒。表5.7列出的水稻入库量仅为丹东供货5110.34吨；表5.8对应七个需求点的水稻出库量合计为1000＋1000＋2700＋2300＋4000＋3000＋2800＝16800吨，相差11689.66吨，与第72页的收发平衡要求冲突。应回查原始求解结果，不能只调整文字。','72、77—78')
add('表5.7 各商品由供应点至海外仓的货物运输量','清州仓水稻流量不守恒。表5.7列水稻入库28300吨，表5.8八个对应需求点合计为3900＋2900＋2900＋7000＋2000＋5000＋3000＋1600＝28300吨；但第80页又把蔚山水稻量写为4000吨。表格内部该部分相符，正文抄录后却不再满足平衡，应统一以经核验的结果为准。','77、79—80')
add('表5.6 运输规划模型求解结果','建仓成本可由表5.4中川崎、水原、龙仁、清州四仓成本相加核对，但头程及配送成本缺乏未舍入明细，且水原水稻流量存在不平衡。应先修正流量，再按运价逐项重算0.68亿元、0.25亿元及1.42亿元总成本，提供可追溯的核算表。','75、77—79')
add('配送运输成本是指货物从海外仓到目标需求点的本地配送费用','算例存在水原向大阪、名古屋等日本城市供货、清州向札幌等日本城市供货，这些属于日韩跨境运输，不能统称本地配送。应区分境内配送与二次跨境运输，并处理相应港口、通关、税费及运输可行性。','77—80')
add('可能因地理位置、运输半径或建仓成本等原因，被优化排除','对哈尔滨未供货的解释混入了模型没有设置的因素。第五章建仓成本属于海外仓，不是供应点固定成本；运输半径也未被设为独立约束。应依据运输单价、供应容量和边际成本分析解释其未使用原因。','78')
add('体现出较强的网络协同效应与经济性','缺少对照方案。仅给出一个最优布局，不能确认协同效应或节约幅度。应与现行网络、各国独立布仓或固定仓数等基准比较，报告成本及服务指标变化。','78')
add('体现出仓库布局对运输效率与供应链韧性的协同优化作用','第五章未设置运输时间、服务可靠性、失效场景或恢复能力指标，无法由费用最小化直接推出运输效率及韧性提升。应补充指标与实验，或将结论限定为满足所设需求与容量约束下的成本优化。','79')
add('运输批量大、频次高，符合大城市消费市场对快速、高效补货的需求特征','模型未设置发运频次、批次或交付时间，表中总运输量不能证明“频次高”及“快速补货”。应删除这些超出模型可识别范围的判断，或增加相应决策与验证。','79')
add('福冈需求玉米7000吨、大豆3000吨、水稻2000吨','水稻需求量抄错。表5.3与表5.8均为4000吨，正文写成2000吨，应核对并统一。','75、78—79')
add('向蔚山需求点供应玉米5000吨、大豆2000吨、水稻4000吨','水稻量与表5.3及表5.8不符，两表均为2000吨。另同段将“大邱”写成“大阪”，对应的10000、4000、5000吨实际属于大邱。两处均应修正。','75、79—80')
add('提升了整体供应链的规模经济效应与物流协同效率','第五章运输费用按货量线性计算，未引入批量折扣、车辆整合或规模相关成本，无法据此识别规模经济效应。应提供与规模相关的成本机制及对照结果，或收窄结论。','80')
add('本节基于模型求解的可行性边界，将海外仓容积利用率变化的范围设置在50%—100%','所谓“容积利用率”在实验中实际是预先给定的有效容量比例，未必等于求解后的实际占用率。应明确调整的是可用容量上限还是实际利用率，并报告各仓占用情况；还应给出50%情景不可行的容量或不可行诊断依据。','81—82')
add('当海外仓容积利用率达到100%最高水平时，系统配置达到最优结构','100%是所测容量上限，不等于整体运营最优。扩大可行容量本就可能降低成本，但高占用还涉及拥堵、作业空间与安全余量，本文未计入这些代价。结论应限定为本次设定和采样范围内的最小目标值。','82')
add('然而，容积利用率过高所带来的边际优化效应有限','数据不支持稳定的边际效应递减：最优成本从80%至90%仅下降0.01亿元，从90%至100%却下降0.11亿元，后一个区间降幅反而增大。应结合离散选址变化解释，避免笼统给出边际收益递减结论。','81—83')
add('可以系统检验所构建物流网络模型的稳定性与解的鲁棒性，确保优化结果在多种环境下具备现实可行性','分别改变需求并重新求解，只表明各确定性情景下存在相应方案，不能证明某一既定网络对未知需求具有鲁棒性。应固定选址方案进行跨情景测试，或改为“分析最优方案对需求变化的敏感性”。','83')
add('海外仓布局由3个扩展至4个，新增了8、16号仓库','依据表5.10，80%需求情景为10、19、20号，90%情景为8、16、19、20号，实际是新增8、16号且撤出10号，净增加1仓。原句遗漏撤出节点；同段总成本写1.31亿元，而表5.10为1.32亿元，也应核对。','83—84')
add('相较于基准需求，供应节点适度扩展','基准需求下供应点为II、III、IV、V，110%情景为I、II、III、V，数量均为4个，仅由I替换IV，不能称数量扩展。应写明替换关系并解释原因。','83—84')
add('网络冗余性虽有助于风险缓冲，但需平衡成本效率与市场响应能力','120%需求情景增加节点，是为满足更高确定性需求，不能据此认定这些节点属于冗余或可提供风险缓冲。应报告备用能力、容量余量或节点失效测试后，再讨论冗余与韧性。','84')
add('首先将各类商品在供应点进行储备，然后运输至建设的海外仓进行中转','第六章应明确两阶段决策时序：哪些信息在选址与备货时已知，哪些信息在运输时揭示，运输量是否可按场景调整。还应说明供应中断前后的存货损失、剩余库存处置及备货成本是否包括采购成本，以解释储备决策的经济含义。','85、87—88')
add('式（6-4）表示对于每个需求点，各海外仓向该需求点运送的商品总量须不小于其实际需求量','需求满足方式说明与模型不一致：对应公式要求严格等于需求，正文却说“不小于”。应明确是否允许超额配送，若允许需说明多余货物处置；若不允许应修正文义。此处涉及服务约束含义。','87')
add('为了克服CVaR的不足，使用MCVaR准则度量风险','对风险度量的解释不准确。CVaR衡量的是尾部损失的平均水平；均值与CVaR的加权组合是兼顾平均费用和尾部风险，并非因为CVaR忽略了更高成本部分。应重写该段，区分置信水平、损失阈值与尾部风险。','88')
add('由于SC的理想性质，可以改变sup和min的阶次','关键等价变换缺乏条件说明。“理想性质”不是可检验的数学条件，应给出适用的极小极大定理及概率集合的凸性、紧致性、目标的连续性和凸凹条件。后续把加权和的最坏期望拆成两个分别取最坏值的部分，也需证明可由同一最坏分布同时实现，否则一般只能得到保守上界。','89—92')
add('因此，本章基于部分概率分布信息，构建了盒子模糊集和多面体模糊集','概率模糊集的有效性和校准缺少说明。盒子集合须确保每个候选分布的概率非负、总和为1，现有构造及参数范围需检验这一点；同时应说明模糊半径与样本量、置信保证的关系，不能仅以若干任意半径替代统计依据。','88—90、93')
add('本章设置5个场景，每个场景发生概率的可能为1/5','只给出场景数量与等概率，未给出五个场景中各供应点可用比例、受阻路径及承载量、各城市分品种需求，也未说明场景生成与相关性处理方法。应提供完整场景表、名义概率及生成依据，才能复现分布鲁棒实验。','93')
add('商品存储成本依据俄速通等平台数据，确定玉米、大豆和水稻的周存储费用分别为130元/吨、120元/吨和150元/吨','应补充可核验的数据出处、日期、费用包含项目及仓储地点。所列为供应点储备成本，应说明平台报价是否适用于国内供应点，是否包含采购、装卸或其他服务，避免误将综合物流报价用作纯周仓储费。','92—93')
add('密度1.39立方米/吨、1.27立方米/吨、1.74立方米/吨','概念与单位不一致：立方米/吨表示单位质量占用体积，即比容，而不是密度。应更正名称并提供数据来源；同时说明粮食品类、含水率及堆存方式如何影响体积换算。','93')
add('国际贸易政策方面采用1%的统一关税税率','统一关税缺乏适用范围说明。中日、中韩及日韩之间的商品税则、原产地待遇和配额条件可能不同，应注明税则年份、商品编码和政策依据，并说明从货值税率换算为单位货物税费的方法。若仅为简化假设，应明确并检验税率敏感性。','93')
add('表6.2展示了模型在盒子和多面体两种模糊集下的选址决策、最优目标值以及储备量结果','表6.2仅有模糊集、海外仓选址结果及最优目标值，未列储备量，与正文宣称不符。应补充各供应点分商品储备量，并给出其容量和场景需求满足情况；后文将该表误称“表4.2”，也应改正。','93')
add('但多面体模糊集下的最优目标值显著高于盒子模糊集','基准值分别为3.2742与3.2736亿元，差0.0006亿元，即6万元，相对差约0.0183%。未报告求解误差或重复实验，不能称“显著高于”；应报告实际差额，并说明求解精度能否区分该差异。','93')
add('这主要由于多面体模糊集具有更复杂的几何结构，覆盖了更广泛的不确定性分布','几何结构更复杂不意味着概率集合更大。应证明本文具体参数下两集合的包含关系或比较其允许概率范围；若不存在包含关系，不能用“覆盖更广”普遍解释目标值高低。','93')
add('对应的风险水平就越高，导致风险规避策略越多','混淆客观风险与模型保守程度。提高置信水平或风险权重改变的是风险评价标准，扩大模糊半径改变的是分布不确定性范围，不能直接等同于现实风险升高或“策略越多”。应分别解释参数含义，并用尾部损失、方案变化等指标检验。','94')
add('风险偏好……情况下','模型采用均值与CVaR的非负加权，即使风险权重较小，也不能据此认定为风险寻求；更合适的是“风险规避程度较低”。而两组对比同时改变置信水平、风险权重和模糊半径，无法将方案变化单独归因于风险态度，应补充控制变量比较。','94—95')
add('这种策略调整虽然能够增强系统应对不确定性的能力，但需要以增加运营成本为代价','3.0107与3.5921亿元是不同风险评价参数下的加权目标值，不能直接把19.3%的增幅解释为实际运营费用增幅。应在同一测试分布与同一成本口径下评价两个方案，分别报告期望费用、尾部风险及可行率。','94—95')
add('盒子模糊集和多面体模糊集下的PDR最大值分别不超过6.40%和6.64%','未给出SP基准的模型定义、基准最优值、参数口径及逐点计算数据，读者无法复核该比例。图6.2、图6.3还使用0.06—0.09的参数，超出前文0.01—0.05的设置范围，应补充对应实验设置及原始结果。','93、95—96')
add('DRO模型以极低的成本获得了双重优势，既规避了概率模糊性，又比传统随机规划模型更鲁棒地利用了分布','仅比较训练内的最优目标值或鲁棒性代价，不能证明鲁棒性优势，也不足以认定代价“极低”。应增加样本外分布扰动、尾部损失和需求满足率测试，并给出可接受成本增量的业务依据。','95、98')
add('海外仓选址数量则仅在容积从90%增加到100%时保持不变','数量描述符合表6.6，但两种模糊集在该区间均以9号替换5号，选址方案发生变化。应明确区分“仓数不变”与“选址不变”，并分析替换节点对成本结构的影响。','96—97')
add('海外仓建设成本占比出现了反常的微幅上升（从29.98%增至29.15%）','数字与“上升”矛盾，图6.4的90%值为28.98%，应先核实是否应为“从28.98%增至29.15%”。此外按表6.6与图示比例估算，90%情景建仓费约3.0994×28.98%＝0.8982亿元，100%约3.0192×29.15%＝0.8801亿元，建仓费反而下降，不能将占比回升解释为建仓费增加。应提供分项费用重核。','97')
add('但5号海外仓被替换为9号海外仓，海外仓建设成本增加','若第六章沿用第五章的建设成本数据，则5号札幌为19601523元、9号京都为15779924元，更换后应减少3821599元，方向与原文相反。若第六章重新估算了建设成本，应列出新表并解释与第五章的差异。','75、92、97')
add('本章以东北东北亚跨境贸易为案例，探讨海外仓选址问题','“东北东北亚”表达重复且地域关系不清，建议改为“以我国东北地区面向东北亚的粮食跨境贸易为案例”。文中所用数据包含人口估计、土地价格推算、等概率场景等，应区分实测数据与模拟假设，避免笼统称全部为实际案例数据。','84、92—93')

